79	#define GET_OP_API_FUNC(apiName) reinterpret_cast<_##apiName>(GetOpApiFuncAddr(#apiName))
80	
81	inline const char* GetOpApiLibName(void) 
82	{
83	  return "libopapi.so";
84	}
