91	inline void* GetOpApiFuncAddrInLib(void* handler, const char* libName, const char* apiName) 
92	{
93	  auto funcAddr = dlsym(handler, apiName);
94	  if (funcAddr == nullptr) {
95	    OP_LOGW("aclnnfallback", "dlsym %s from %s failed, error:%s.", apiName, libName, dlerror());
96	  }
97	  return funcAddr;
98	}
