100	inline void* GetOpApiLibHandler(const char* libName) 
101	{
102	  auto handler = dlopen(libName, RTLD_LAZY);
103	  if (handler == nullptr) {
104	    OP_LOGW("aclnnfallback", "dlopen %s failed, error:%s.", libName, dlerror());
105	  }
106	  return handler;
107	}
108	
109	inline void* GetAclnnArrdByApiName(const char *apiName) 
110	{
111	    vector<std:: string> libs = {"libaclnn_ops_infer.so", "libaclnn_ops_train.so", "libaclnn_math.so",
112	                                 "libaclnn_rand.so", "libaclnn_sparse.so", "libaclnn_fft.so"};
113	    for (const auto &libName : libs) {
114	        static auto libHandler = GetOpApiLibHandler(libName.c_str());
115	        if (libHandler != nullptr) {
116	            auto funcAddr = GetOpApiFuncAddrInLib(libHandler, libName.c_str(), apiName);
117	            if (funcAddr != nullptr) {
118	                return funcAddr;
119	            }
120	        }
121	    }
122	    OP_LOGE("aclnnfallback", "api %s can't find in any aclnn lib.", apiName);
123	    return nullptr;
124	}
125	
126	inline void* GetOpApiFuncAddr(const char* apiName) 
127	{
128	  static auto custOpApiHandler = GetOpApiLibHandler(GetCustOpApiLibName());
129	  if (custOpApiHandler != nullptr) {
130	    auto funcAddr = GetOpApiFuncAddrInLib(custOpApiHandler, GetCustOpApiLibName(), apiName);
131	    if (funcAddr != nullptr) {
132	      return funcAddr;
133	    }
134	  }
135	
136	  static auto opApiHandler = GetOpApiLibHandler(GetOpApiLibName());
137	  if (opApiHandler != nullptr) {
138	      auto funcAddr = GetOpApiFuncAddrInLib(opApiHandler, GetOpApiLibName(), apiName);
139	      if (funcAddr != nullptr) {
140	          return funcAddr;
141	      }
142	  }
143	  OP_LOGD("aclnnfallback", "opapi lib is not exist,will use aclnn lib.");
144	  return GetAclnnArrdByApiName(apiName);
145	}
