162	inline aclDataType GetConvertType(const gert::Tensor* ge_tensor) 
163	{
164	  // convert data type
165	  auto dataType_ge = ge_tensor->GetDataType();
166	  auto dataType = aclDataType::ACL_FLOAT16;
167	  if (dataType_ge == DT_FLOAT) {
168	    dataType = aclDataType::ACL_FLOAT;
169	  } else if (dataType_ge == DT_BF16) {
170	    dataType = aclDataType::ACL_BF16;
171	  } else if (dataType_ge == DT_BOOL) {
172	    dataType = aclDataType::ACL_BOOL;
173	  } else if (dataType_ge == DT_INT64) {
174	    dataType = aclDataType::ACL_INT64;
175	  } else if (dataType_ge == DT_INT32) {
176	    dataType = aclDataType::ACL_INT32;
177	  } else if (dataType_ge == DT_UINT64) {
178	    dataType = aclDataType::ACL_UINT64;
179	  } else if (dataType_ge == DT_UINT32) {
180	    dataType = aclDataType::ACL_UINT32;
181	  } else if (dataType_ge == DT_INT8) {
182	    dataType = aclDataType::ACL_INT8;
183	  } else if (dataType_ge == DT_UINT8) {
184	    dataType = aclDataType::ACL_UINT8;
185	  } else if (dataType_ge == DT_INT4) {
186	    dataType = aclDataType::ACL_INT4;
187	  } else {
188	    dataType = aclDataType::ACL_FLOAT16;
189	  }
190	
191	  return dataType;
192	}
193	
194	aclTensor* ConvertType(const gert::Tensor* ge_tensor) 
195	{
196	  if (ge_tensor == nullptr) {
197	    return nullptr;
198	  }
199	
200	  static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
201	  OP_CHECK_IF(aclCreateTensor == nullptr, OP_LOGE("aclnnfallback", "aclCreateTensor nullptr"), return nullptr);
202	
203	  void* device_addr = nullptr;
204	  device_addr = const_cast<void*>(ge_tensor->GetAddr());
205	
206	  auto dataType = GetConvertType(ge_tensor);
207	
208	  OP_LOGD("aclnnfallback", "aclCreateTensor: tensor type is %d", dataType);
209	
210	  // convert shape
211	  auto gert_shape = ge_tensor->GetStorageShape();
212	  std::vector<int64_t> shape;
213	  for (size_t i = 0; i < gert_shape.GetDimNum(); ++i) {
214	    shape.push_back(gert_shape.GetDim(i));
215	  }
216	
217	  // 计算连续tensor的strides
218	  std::vector<int64_t> strides(shape.size(), 1);
219	  for (int64_t i = shape.size() - 2; i >= 0; i--) {
220	    strides[i] = shape[i + 1] * strides[i + 1];
221	  }
222	
223	  aclTensor* out = aclCreateTensor(shape.data(), shape.size(), dataType, strides.data(),
224	                                   0, aclFormat::ACL_FORMAT_ND,
225	                                   shape.data(), shape.size(), device_addr);
226	
227	  OP_CHECK_IF(out == nullptr,
228	    OP_LOGE("aclnnfallback", "out nullptr"), return nullptr);
229	
230	  return out;
231	}
