239	  OP_CHECK_IF(aclCreateTensorList == nullptr,
240	    OP_LOGE("aclnnfallback", "ge_tenserList size 0"), return nullptr);
241	
242	  std::vector<aclTensor*> tmp;
243	  for (size_t i = 0; i < ge_tenserList.size(); i++) {
244	    auto t_acl = ConvertType(ge_tenserList[i]);
245	    tmp.push_back(t_acl);
246	  }
247	
248	  aclTensorList* tensorList = aclCreateTensorList(tmp.data(), tmp.size());
249	  return tensorList;
250	}
