270	aclTensor* ConvertMmType(const gert::Tensor* ge_tensor, bool transpose, bool enable_NZ=false) 
271	{
272	  if (ge_tensor == nullptr) {
273	    return nullptr;
274	  }
275	  auto gert_shape = ge_tensor->GetStorageShape();
276	  if (gert_shape.GetDimNum() <= 1) {
277	    return ConvertType(ge_tensor);
278	  }
279	
280	  static const auto aclCreateTensor = GET_OP_API_FUNC(aclCreateTensor);
281	  OP_CHECK_IF(aclCreateTensor == nullptr, OP_LOGE("aclnnfallback", "aclCreateTensor nullptr"), return nullptr);
282	
283	  void* device_addr = const_cast<void*>(ge_tensor->GetAddr());
284	  // convert data type
285	  auto dataType_ge = ge_tensor->GetDataType();
286	  auto dataType = ToAclDataType(dataType_ge);
287	  // convert shape
288	  std::vector<int64_t> shape;
289	  for (size_t i = 0; i < gert_shape.GetDimNum(); ++i) {
290	    shape.push_back(gert_shape.GetDim(i));
291	  }
292	  // 计算连续tensor的strides
293	  std::vector<int64_t> strides(shape.size(), 1);
294	  for (int64_t i = shape.size() - 2; i >= 0; i--) {
295	    strides[i] = shape[i + 1] * strides[i + 1];
296	  }
297	
298	  auto viewShape = shape;
299	  // 对于transpose后的tensor对后两维度进行strides, viewShape转换
300	  if (transpose) {
301	    // dimM 为倒数第二维， dimN 为倒数第一维度
302	    auto dimM = shape.size() - 2;
303	    auto dimN = shape.size() - 1;
304	    auto swap =  strides[dimN];
305	    strides[dimN] = strides[dimM];
306	    strides[dimM] = swap;
307	    // 修改viewShape
308	    viewShape[dimN] = shape[dimM];
309	    viewShape[dimM] = shape[dimN];
310	  }
311	  auto acl_format = aclFormat::ACL_FORMAT_ND;
312	  if (enable_NZ && GetPrimaryFormat(ge_tensor->GetStorageFormat()) == ge::Format::FORMAT_FRACTAL_NZ) {
313	    acl_format = aclFormat::ACL_FORMAT_FRACTAL_NZ;
314	  }
315	  aclTensor* out = aclCreateTensor(viewShape.data(), shape.size(), dataType, strides.data(),
316	                                   0, acl_format, shape.data(), shape.size(), device_addr);
317	  OP_CHECK_IF(out == nullptr, OP_LOGE("aclnnfallback", "out nullptr"), return nullptr);
318	
319	  return out;
320	}
