374	template <typename Tuple>
375	void ReleaseConvertTypes(Tuple& t) 
376	{
377	  static constexpr auto size = std::tuple_size<Tuple>::value;
378	  CallRelease(t, std_utils::make_index_sequence<size>{});
379	}
