381	template <typename... Ts>
382	auto ConvertTypes(Ts&... args) -> decltype(std::make_tuple(ConvertType(args)...)) 
383	{
384	    auto tp = std::make_tuple(ConvertType(args)...);
385	    return tp;
386	}
387	
388	template <typename Function, typename Tuple, size_t... I>
389	auto call(Function f, Tuple t, std_utils::index_sequence<I...>)  -> int 
390	{
391	  return f(std::get<I>(t)...);
392	}
393	
394	template <typename Function, typename Tuple>
395	auto call(Function f, Tuple t) -> int 
396	{
397	  static constexpr auto size = std::tuple_size<Tuple>::value;
398	  return call(f, t, std_utils::make_index_sequence<size>{});
399	}
