401	template <typename Tuple, size_t... I>
402	auto ConvertToOpApiFunc(const Tuple& params, void* opApiAddr, std_utils::index_sequence<I...>)
403	    -> int (*)(typename std::decay<decltype(std::get<I>(params))>::type...) 
404	{
405	    using OpApiFunc = int (*)(typename std::decay<decltype(std::get<I>(params))>::type...);
406	    auto func = reinterpret_cast<OpApiFunc>(opApiAddr);
407	    return func;
408	}
409	
410	template <typename Tuple>
411	auto ConvertToOpApiFunc(const Tuple& params, void* opApiAddr)
412	    -> typename std::enable_if<std::tuple_size<Tuple>::value != 0,
413	    decltype(ConvertToOpApiFunc(params, opApiAddr, 
414	        std_utils::make_index_sequence<std::tuple_size<Tuple>::value>{}))>::type 
415	{
416	    static constexpr auto size = std::tuple_size<Tuple>::value;
417	    return ConvertToOpApiFunc(params, opApiAddr, std_utils::make_index_sequence<size>{});
418	}
