420	using InitHugeMemThreadLocal = int (*)(void*, bool);
421	using UnInitHugeMemThreadLocal = void (*)(void*, bool);
422	using ReleaseHugeMem = void (*)(void*, bool);
423	using PTAGetExecCache = aclOpExecutor* (*)(uint64_t, uint64_t*);
424	using InitPTACacheThreadLocal = void (*)();
425	using SetPTAHashKey = void (*)(uint64_t);
426	using CanUsePTACache = bool (*)(const char*);
427	
428	using ResetCacheThreadLocal = void (*)();
429	
430	#define EXEC_OPAPI_CMD(aclnn_api, ...)                                                                               \
431	  ({                                                                                                                 \
432	    static auto ret = GRAPH_SUCCESS;                                                                                 \
433	    do {                                                                                                             \
434	      static const auto ResetCacheThreadLocalAddr = GetOpApiFuncAddr("ResetCacheThreadLocal");                       \
435	      static const auto getWorkspaceSizeFuncAddr = GetOpApiFuncAddr(#aclnn_api "GetWorkspaceSize");                  \
436	      static const auto opApiFuncAddr = GetOpApiFuncAddr(#aclnn_api);                                                \
437	      if (getWorkspaceSizeFuncAddr == nullptr || opApiFuncAddr == nullptr || ResetCacheThreadLocalAddr == nullptr) { \
438	        OP_LOGE("aclnnfallback", "%s or %s not in  %s or %s  or ResetCacheThreadLocal not found.",                   \
439	                #aclnn_api "GetWorkspaceSize", #aclnn_api, GetOpApiLibName(), GetOpApiLibName());                    \
440	        ret = GRAPH_FAILED;                                                                                          \
441	        break;                                                                                                       \
442	      }                                                                                                              \
443	      auto ResetCacheThreadLocalFunc = reinterpret_cast<ResetCacheThreadLocal>(ResetCacheThreadLocalAddr);           \
444	      ResetCacheThreadLocalFunc();                                                                                   \
445	      uint64_t workspace_size = 0;                                                                                   \
446	      uint64_t* workspace_size_addr = &workspace_size;                                                               \
447	      aclOpExecutor* executor = nullptr;                                                                             \
448	      aclOpExecutor** executor_addr = &executor;                                                                     \
449	      auto converted_params = ConvertTypes(__VA_ARGS__, workspace_size_addr, executor_addr);                         \
450	      static auto getWorkspaceSizeFunc = ConvertToOpApiFunc(converted_params, getWorkspaceSizeFuncAddr);             \
451	      auto workspace_status = call(getWorkspaceSizeFunc, converted_params);                                          \
452	      if (workspace_status != 0) {                                                                                   \
453	        OP_LOGE("aclnnfallback", "call %s failed:", #aclnn_api);                                                     \
454	        ret = GRAPH_FAILED;                                                                                          \
455	        break;                                                                                                       \
456	      }                                                                                                              \
457	      void* workspace_addr = nullptr;                                                                                \
458	      if (workspace_size > 0) {                                                                                      \
459	        workspace_addr = host_api_ctx->MallocWorkspace(workspace_size);                                              \
460	        if (workspace_addr == nullptr) {                                                                             \
461	          OP_LOGE("aclnnfallback", "call %s allocate workspace failed", #aclnn_api);                                 \
462	          ret = GRAPH_FAILED;                                                                                        \
463	          break;                                                                                                     \
464	        }                                                                                                            \
465	      }                                                                                                              \
466	      auto acl_stream = host_api_ctx->GetStream();                                                                   \
467	      auto acl_call = [converted_params, workspace_addr, workspace_size, host_api_ctx, acl_stream,                   \
468	                       executor]() -> int {                                                                          \
469	        using OpApiFunc = int (*)(void*, uint64_t, aclOpExecutor*, const aclrtStream);                               \
470	        OpApiFunc opApiFunc = reinterpret_cast<OpApiFunc>(opApiFuncAddr);                                            \
471	        auto api_ret_inner = opApiFunc(workspace_addr, workspace_size,                                               \
472	                                       executor, acl_stream);                                                        \
473	        ReleaseConvertTypes(converted_params);                                                                       \
474	        host_api_ctx->FreeWorkspace();                                                                               \
475	        if (api_ret_inner != 0) {                                                                                          \
476	          OP_LOGE("aclnnfallback", "call %s allocate workspace failed api_ret_inner: %d", 
477	                  #aclnn_api, api_ret_inner);                                                                        \
478	          return GRAPH_FAILED;                                                                                       \
479	        }                                                                                                            \
480	        return api_ret_inner;                                                                                              \
481	      };                                                                                                             \
482	                                                                                                                     \
483	      ret = acl_call();                                                                                              \
484	    } while (false);                                                                                                 \
485	    (ret);                                                                                                           \
486	  })
487	
488	}  // namespace fallback
489	
490	#endif  //  ACLNNFALLBACK_OPAPI_H_
